// func fdctQuant16(b *block, tab *[3][64]uint16, out *[64]int16)
//
// The coefficients of the samples of b, divided by the quantization table
// whose reciprocals, corrections and scales (recip16) are tab[0], tab[1]
// and tab[2], in natural order, into out in zig-zag order. b is not
// changed.
TEXT ·fdctQuant16(SB), NOSPLIT, $0-24
	MOVQ b+0(FP), AX
	MOVQ tab+8(FP), BX
	MOVQ out+16(FP), DI
	// The samples as 16-bit words, less 128: two rows a register.
	VMOVDQU 0(AX), Y8
	VPACKSSDW 32(AX), Y8, Y4
	VPERMQ $0xd8, Y4, Y4
	VPSUBW fdct_c128<>(SB), Y4, Y4
	VMOVDQU 64(AX), Y8
	VPACKSSDW 96(AX), Y8, Y5
	VPERMQ $0xd8, Y5, Y5
	VPSUBW fdct_c128<>(SB), Y5, Y5
	VMOVDQU 128(AX), Y8
	VPACKSSDW 160(AX), Y8, Y6
	VPERMQ $0xd8, Y6, Y6
	VPSUBW fdct_c128<>(SB), Y6, Y6
	VMOVDQU 192(AX), Y8
	VPACKSSDW 224(AX), Y8, Y7
	VPERMQ $0xd8, Y7, Y7
	VPSUBW fdct_c128<>(SB), Y7, Y7
	// Pass 1: the rows.
	VPERM2I128 $0x20, Y6, Y4, Y0
	VPERM2I128 $0x31, Y6, Y4, Y1
	VPERM2I128 $0x20, Y7, Y5, Y2
	VPERM2I128 $0x31, Y7, Y5, Y3
	VPUNPCKLWD Y1, Y0, Y4
	VPUNPCKHWD Y1, Y0, Y5
	VPUNPCKLWD Y3, Y2, Y6
	VPUNPCKHWD Y3, Y2, Y7
	VPUNPCKLDQ Y6, Y4, Y0
	VPUNPCKHDQ Y6, Y4, Y1
	VPUNPCKLDQ Y7, Y5, Y2
	VPUNPCKHDQ Y7, Y5, Y3
	VPERMQ $0x8d, Y0, Y0
	VPERMQ $0x8d, Y1, Y1
	VPERMQ $0xd8, Y2, Y2
	VPERMQ $0xd8, Y3, Y3
	VPSUBW Y3, Y0, Y4
	VPADDW Y3, Y0, Y5
	VPADDW Y2, Y1, Y6
	VPSUBW Y2, Y1, Y7
	VPERM2I128 $0x01, Y5, Y5, Y5
	VPADDW Y6, Y5, Y0
